function multiply(a, b) {
  return a * b;
}
function assertEqual(actual, expected, name) {
  console.log(actual === expected ? 'PASS: ' + name : 'FAIL: ' + name);
}
assertEqual(multiply(3, 4), 12, '3*4');
assertEqual(multiply(0, 9), 0, '0*9');

