exercises.solution:
function discount(price, pct) {
  return price - price * pct / 100;
}
function assertEqual(actual, expected, name) {
  console.log(actual === expected ? 'PASS: ' + name : 'FAIL: ' + name);
}
assertEqual(discount(100, 10), 90, 'normal discount');
assertEqual(discount(100, 0), 100, 'zero percent');
assertEqual(discount(100, 100), 0, 'full discount');
assertEqual(discount(0, 10), 0, 'zero price');

